93	  userChoice: Promise<{ outcome: 'accepted' | 'dismissed' }>;
94	}
95	
96	type WorkContextThemeSource =
97	  | {
98	      theme?: WorkContextThemeCfg | null;
99	    }
100	  | null
101	  | undefined;
102	
103	export const getBackgroundOverlayOpacity = (context: WorkContextThemeSource): number => {
104	  const baseOpacity = context?.theme?.backgroundOverlayOpacity ?? 20;
105	  return baseOpacity * 0.01;
106	};
