111	@Component({
112	  selector: 'app-root',
113	  templateUrl: './app.component.html',
114	  styleUrls: ['./app.component.scss'],
115	  animations: [
116	    expandAnimation,
117	    warpRouteAnimation,
118	    fadeAnimation,
119	    warpAnimation,
120	    warpInAnimation,
121	  ],
122	  changeDetection: ChangeDetectionStrategy.OnPush,
123	  imports: [
124	    AddTaskBarComponent,
125	    Dir,
126	    MagicSideNavComponent,
127	    MainHeaderComponent,
128	    BannerComponent,
129	    RightPanelComponent,
130	    RouterOutlet,
131	    GlobalProgressBarComponent,
132	    FocusModeOverlayComponent,
133	    MatMenuItem,
134	    MatIcon,
135	    TranslatePipe,
136	    ContextMenuComponent,
137	    MobileBottomNavComponent,
138	    OnboardingPresetSelectionComponent,
139	    OnboardingHintComponent,
