141	})
142	export class AppComponent implements OnDestroy, AfterViewInit {
143	  private _globalConfigService = inject(GlobalConfigService);
144	  private _shortcutService = inject(ShortcutService);
145	  private _bannerService = inject(BannerService);
146	  private _snackService = inject(SnackService);
147	  private _globalThemeService = inject(GlobalThemeService);
148	  private _languageService = inject(LanguageService);
149	  private _activatedRoute = inject(ActivatedRoute);
150	  private _matDialog = inject(MatDialog);
151	  private _markdownPasteService = inject(MarkdownPasteService);
152	  private _taskService = inject(TaskService);
153	  private _projectService = inject(ProjectService);
154	  private _tagService = inject(TagService);
155	  private _destroyRef = inject(DestroyRef);
156	  private _noteStartupBannerService = inject(NoteStartupBannerService);
157	  private _ngZone = inject(NgZone);
158	  private _document = inject(DOCUMENT, { optional: true });
159	  private _startupService = inject(StartupService);
160	  // Injected for side-effect: creates example tasks on first run
161	  private _exampleTasksService = inject(ExampleTasksService);
162	  // Injected for side-effect: loads per-instance task widget settings from
163	  // localStorage and pushes them to the Electron main process at app boot,
164	  // before the user opens the (lazy-loaded) Settings page.
165	  private _taskWidgetSettingsService = inject(TaskWidgetSettingsService);
166	  private _keyboardLayoutService = inject(KeyboardLayoutService);
167	  private _dataInitStateService = inject(DataInitStateService);
168	  private _materialIconsLoaderService = inject(MaterialIconsLoaderService);
169	  readonly onboardingHintService = inject(OnboardingHintService);
170	
171	  private _syncTriggerService = inject(SyncTriggerService);
172	  readonly workContextService = inject(WorkContextService);
173	  readonly layoutService = inject(LayoutService);
174	  readonly globalThemeService = inject(GlobalThemeService);
175	  readonly _store = inject(Store);
176	  private _sectionService = inject(SectionService);
177	  private _browserTitleService = inject(BrowserTitleService);
178	  private _hasShownLegacyFileBgSnack = false;
179	  readonly T = T;
180	  readonly TODAY_TAG_ID = TODAY_TAG.id;
181	  readonly isShowMobileButtonNav = this.layoutService.isShowMobileBottomNav;
182	
183	  @ViewChild('routeWrapper', { read: ElementRef }) routeWrapper?: ElementRef<HTMLElement>;
184	  @ViewChild(RouterOutlet) private _routerOutlet?: RouterOutlet;
185	
186	  @HostBinding('class.isWorkViewScrolled') get isWorkViewScrolledClass(): boolean {
187	    return this.layoutService.isWorkViewScrolled();
188	  }
189	
190	  @HostBinding('@.disabled') get isDisableAnimations(): boolean {
191	    return this._isDisableAnimations();
192	  }
193	
194	  private _isDisableAnimations = computed(() => {
195	    const misc = this._globalConfigService.misc();
196	    return misc?.isDisableAnimations ?? false;
197	  });
198	
199	  // Experimental: vertical action strip on the right edge instead of the
200	  // horizontal top header. Switches the DOM layout live (see template).
201	  readonly isVerticalActionBar = computed(
202	    () => this._globalConfigService.misc()?.isVerticalActionBar ?? false,
203	  );
204	
205	  isRTL: boolean = false;
206	
207	  private _isOverlayShownFromStore = toSignal(this._store.select(selectIsOverlayShown), {
208	    initialValue: false,
209	  });
210	
211	  // Only show focus overlay if both the store says to show it AND the feature is enabled
212	  isShowFocusOverlay = computed(
213	    () =>
214	      this._isOverlayShownFromStore() &&
215	      this._globalConfigService.appFeatures().isFocusModeEnabled,
216	  );
217	
218	  private readonly _activeWorkContextId = toSignal(
219	    this.workContextService.activeWorkContextId$,
220	    { initialValue: null },
221	  );
222	
223	  private readonly _activeWorkContext = toSignal(
224	    this.workContextService.activeWorkContext$,
225	    { initialValue: null },
226	  );
227	  readonly resolvedBgImage = signal<string | null>(null);
228	
229	  isShowOnboardingPresets = signal(
230	    !localStorage.getItem(LS.ONBOARDING_PRESET_DONE) &&
231	      !localStorage.getItem(LS.IS_SKIP_TOUR),
232	  );
233	
234	  private _subs: Subscription = new Subscription();
235	
236	  constructor() {
237	    this._startupService.init();
238	    void this._materialIconsLoaderService.ensureFontReady();
239	
240	    // Skip onboarding for existing users with data
241	    if (this.isShowOnboardingPresets()) {
242	      this._dataInitStateService.isAllDataLoadedInitially$
243	        .pipe(
244	          concatMap(() => this._projectService.list$),
245	          first(),
246	        )
247	        .subscribe((projectList) => {
248	          if (projectList.length > 2) {
249	            localStorage.setItem(LS.ONBOARDING_PRESET_DONE, 'true');
250	            this.isShowOnboardingPresets.set(false);
251	          }
252	        });
253	    }
254	
255	    // Clear app entrance animation after it completes
256	    if (this.isAppEntrance()) {
257	      setTimeout(() => {
258	        this.isAppEntrance.set(false);
259	      }, ENTRANCE_ANIMATION_DURATION);
260	    }
261	
262	    // Use effect to react to language RTL changes
263	    effect(() => {
264	      const val = this._languageService.isLangRTL();
265	      this.isRTL = val;
266	      document.dir = this.isRTL ? 'rtl' : 'ltr';
267	    });
268	
269	    this._subs.add(
270	      this._activatedRoute.queryParams.subscribe((params) => {
271	        if (!!params.focusItem) {
272	          recordSearchNavDebug('appComponent:focusQueryParam', {
273	            focusItem: params.focusItem,
274	            url: window.location.pathname + window.location.search,
275	          });
276	          this._focusElement(params.focusItem);
277	        }
278	      }),
279	    );
280	
281	    // init theme and body class handlers
282	    this._globalThemeService.init();
283	
284	    let bgResolveRequestId = 0;
285	    effect(() => {
286	      const bgImage = this._globalThemeService.backgroundImg();
287	      const currentRequestId = ++bgResolveRequestId;
288	      if (
289	        typeof bgImage === 'string' &&
290	        bgImage.startsWith('file://') &&
291	        !this._hasShownLegacyFileBgSnack
292	      ) {
293	        this._hasShownLegacyFileBgSnack = true;
294	        this._snackService.open({
295	          msg: T.F.PROJECT.FORM_THEME.S_BACKGROUND_IMAGE_RESELECT_REQUIRED,
296	          type: 'WARNING',
297	          config: { duration: 0 },
298	        });
299	      }
300	      void resolveBgImageToDataUrl(bgImage).then((resolved) => {
301	        // Ignore stale resolutions when the source changed mid-read.
302	        if (currentRequestId === bgResolveRequestId) {
303	          this.resolvedBgImage.set(resolved);
304	        }
305	      });
306	    });
307	
308	    this._syncTriggerService.afterInitialSyncDoneAndDataLoadedInitially$
309	      .pipe(take(1))
310	      .subscribe(() => {
311	        void this._noteStartupBannerService.showLastNoteIfNeeded();
312	      });
313	
314	    // ! For keyboard shortcuts to work correctly with any layouts (QWERTZ/AZERTY/etc) - user's keyboard layout must be presaved
315	    // Connect the service to the utility functions
316	    setKeyboardLayoutService(this._keyboardLayoutService);
317	    // Defer keyboard layout detection to idle time for better initial load performance,
318	    // EXCEPT on macOS Electron where it is needed eagerly for the initial global shortcut registration.
319	    if (IS_ELECTRON && IS_MAC) {
320	      void this._keyboardLayoutService.saveUserLayout();
321	    } else if (typeof requestIdleCallback === 'function') {
322	      requestIdleCallback(() => this._keyboardLayoutService.saveUserLayout());
323	    } else {
324	      setTimeout(() => this._keyboardLayoutService.saveUserLayout(), 0);
325	    }
326	  }
327	
328	  @HostListener('document:paste', ['$event']) onPaste(ev: ClipboardEvent): void {
329	    // Skip handling inside input elements
330	    const target = ev.target as HTMLElement;
331	    if (isInputElement(target)) return;
332	
333	    const clipboardData = ev.clipboardData;
334	    if (!clipboardData) return;
335	
336	    const pastedText = clipboardData.getData('text/plain');
337	    if (!pastedText) return;
338	
339	    if (!this._markdownPasteService.isMarkdownTaskList(pastedText)) return;
340	
341	    // Prevent default paste behavior
342	    ev.preventDefault();
343	
344	    // Check if paste is happening on a task element
345	    let taskId: string | null = null;
346	    let taskTitle: string | null = null;
347	    let isSubTask = false;
348	
349	    // Find the nearest task element via the data-task-id attribute (set
350	    // on the <task> host). Avoids brittle id-prefix scans that could match
351	    // unrelated elements whose id happens to start with "t-".
352	    const taskEl = target.closest<HTMLElement>('[data-task-id]');
353	
354	    if (taskEl) {
355	      taskId = taskEl.getAttribute('data-task-id');
356	    }
357	
358	    if (taskId) {
359	      // Get task data to determine if it's a sub-task
360	      this._taskService.getByIdOnce$(taskId).subscribe((task) => {
361	        if (task) {
362	          taskTitle = task.title;
363	          isSubTask = !!task.parentId;
364	          this._markdownPasteService.handleMarkdownPaste(
365	            pastedText,
366	            taskId,
367	            taskTitle,
368	            isSubTask,
369	          );
370	        } else {
371	          // Fallback: handle as parent tasks if task not found
372	          this._markdownPasteService.handleMarkdownPaste(pastedText, null);
373	        }
374	      });
375	    } else {
376	      // Handle as parent tasks since no specific task context
377	      this._markdownPasteService.handleMarkdownPaste(pastedText, null);
378	    }
379	  }
380	
381	  @HostListener('window:beforeinstallprompt', ['$event']) onBeforeInstallPrompt(
382	    e: BeforeInstallPromptEvent,
383	  ): void {
384	    if (
385	      IS_ELECTRON ||
386	      localStorage.getItem(LS.WEB_APP_INSTALL) ||
387	      OnboardingHintService.isOnboardingInProgress()
388	    ) {
389	      return;
390	    }
391	
392	    // Prevent Chrome 67 and earlier from automatically showing the prompt
