439	      //   ? this.startX() - event.clientX
440	      event.clientX - this.startX();
441	
442	    const potentialWidth = this.startWidth() + deltaX;
443	    const { collapseThreshold, expandThreshold, minWidth, maxWidth } = this.config();
444	
445	    // Handle seamless mode transitions
446	    if (this.isFullMode()) {
447	      // Currently fullMode - check for compactMode threshold
448	      if (potentialWidth < collapseThreshold) {
449	        // Auto-switch to compactMode without releasing mouse
450	        this.isFullMode.set(false);
