508	  private _handleArrowNavigation(event: KeyboardEvent): void {
509	    // Get all focusable elements in the nav
510	    const focusableElements = this._getFocusableNavElements();
511	
512	    if (focusableElements.length === 0) {
513	      return;
514	    }
515	
516	    const activeElement = document.activeElement as HTMLElement;
517	    const currentIndex = focusableElements.indexOf(activeElement);
518	
519	    event.preventDefault();
520	    event.stopPropagation();
521	
522	    let nextIndex: number;
523	    if (currentIndex === -1) {
524	      // No nav element focused, focus first element
525	      nextIndex = 0;
526	    } else if (event.key === 'ArrowDown') {
527	      nextIndex = (currentIndex + 1) % focusableElements.length;
528	    } else if (event.key === 'ArrowUp') {
529	      nextIndex = currentIndex === 0 ? focusableElements.length - 1 : currentIndex - 1;
530	    } else {
531	      return;
532	    }
533	
534	    focusableElements[nextIndex]?.focus();
535	  }
