537	  private _getFocusableNavElements(): HTMLElement[] {
538	    const nav = document.querySelector('.nav-sidenav');
539	    if (!nav) {
540	      return [];
541	    }
542	
543	    // Get the sidenav toggle button first (if visible)
544	    const toggleButton = nav.querySelector('.mode-toggle') as HTMLElement;
545	    const focusableElements: HTMLElement[] = [];
546	
547	    if (toggleButton) {
548	      const styles = window.getComputedStyle(toggleButton);
549	      if (styles.display !== 'none' && styles.visibility !== 'hidden') {
550	        toggleButton.setAttribute('tabindex', '0');
551	        focusableElements.push(toggleButton);
552	      }
553	    }
554	
555	    // Get all nav-link elements (these are the actual clickable items)
556	    // Also get any mat-menu-item elements which are used for nav items
557	    const selector = '.nav-link, [mat-menu-item]';
558	    const allElements = Array.from(nav.querySelectorAll(selector)) as HTMLElement[];
559	
560	    // Filter to only get elements within the nav-list
561	    const navList = nav.querySelector('.nav-list');
562	    if (!navList) {
563	      return focusableElements; // Return just the toggle if no nav list
564	    }
565	
566	    const navListElements = allElements.filter((el) => {
567	      // Make sure the element is inside nav-list
568	      const isInNavList = navList.contains(el);
569	
570	      // Check if it's actually interactive (button or link)
571	      const tagName = el.tagName.toLowerCase();
572	      const isInteractive = tagName === 'button' || tagName === 'a';
573	
574	      // Check visibility
575	      const styles = window.getComputedStyle(el);
576	      const isVisible =
577	        styles.display !== 'none' &&
578	        styles.visibility !== 'hidden' &&
579	        styles.opacity !== '0';
580	
581	      // Exclude settings buttons and other non-navigation buttons
582	      const isSettingsBtn = el.classList.contains('additional-btn');
583	
584	      return isInNavList && isInteractive && isVisible && !isSettingsBtn;
585	    });
586	
587	    // Set tabindex on nav list elements to make them focusable
588	    navListElements.forEach((el) => {
589	      if (!el.hasAttribute('tabindex') || el.getAttribute('tabindex') === '-1') {
590	        el.setAttribute('tabindex', '0');
591	      }
592	    });
593	
594	    // Combine toggle button (if present) with nav list elements
595	    const allFocusable = [...focusableElements, ...navListElements];
596	
597	    return allFocusable;
598	  }
