600	  private _handleEscapeKey(event: KeyboardEvent): void {
601	    // Unfocus any currently focused navigation element
602	    const activeElement = document.activeElement as HTMLElement;
603	    const navSidebar = document.querySelector('.nav-sidenav');
604	
605	    // Check if the currently focused element is within the navigation
606	    if (navSidebar && navSidebar.contains(activeElement)) {
607	      event.preventDefault();
608	      event.stopPropagation();
609	
610	      this._unfocusNavAndFocusTask();
611	    }
612	  }
