614	  private _unfocusNavAndFocusTask(): void {
615	    const activeElement = document.activeElement as HTMLElement;
616	    if (activeElement?.blur) {
617	      activeElement.blur();
618	    }
619	    setTimeout(() => {
620	      this._taskService.focusFirstTaskIfVisible();
621	    }, FOCUS_DELAY_MS);
622	  }
