624	  // Public method to toggle nav focus (for keyboard shortcuts)
625	  toggleNavFocus(): void {
626	    // Check if any nav element is currently focused
627	    const activeElement = document.activeElement as HTMLElement;
628	    const navSidebar = document.querySelector('.nav-sidenav');
629	    const isNavFocused = navSidebar && navSidebar.contains(activeElement);
630	
631	    // If on mobile
632	    if (this.isMobile()) {
633	      if (this.showMobileMenuOverlay()) {
634	        // If mobile overlay is open and nav is focused, close it
635	        if (isNavFocused) {
636	          this.showMobileMenuOverlay.set(false);
637	          this._unfocusNavAndFocusTask();
638	        } else {
639	          // Mobile overlay is open but nav not focused, focus it
640	          this._focusFirstNavElement();
641	        }
642	      } else {
643	        // Mobile overlay is closed, open it and focus
644	        this.showMobileMenuOverlay.set(true);
645	        setTimeout(() => {
646	          this._focusFirstNavElement();
647	        });
648	      }
649	      return;
650	    }
651	
652	    // Desktop behavior: toggle focus
653	    if (isNavFocused) {
654	      // Nav is already focused, unfocus it
655	      this._unfocusNavAndFocusTask();
656	    } else {
657	      // Nav is not focused, focus it
658	      this._focusFirstNavElement();
659	    }
660	  }
661	
662	  private _focusFirstNavElement(): void {
663	    const focusableElements = this._getFocusableNavElements();
664	    if (focusableElements.length > 0) {
665	      focusableElements[0].focus();
666	    }
667	  }
668	
669	  private _handlePointerUp(event: MouseEvent | TouchEvent): void {
670	    const draggedTask = this._externalDragService.activeTask();
671	
672	    // exclude recurring tasks
673	    if (!draggedTask || draggedTask.repeatCfgId) {
674	      return;
675	    }
676	
677	    const pointerPos = getPointerPosition(event);
678	    if (!pointerPos) {
679	      return;
680	    }
681	
682	    const navItemElement = document
683	      .elementFromPoint(pointerPos.x, pointerPos.y)
684	      ?.closest('nav-item');
685	    if (!navItemElement) {
686	      return;
687	    }
688	
689	    if (navItemElement.hasAttribute('data-project-id')) {
690	      // Task is dropped on a project
691	
692	      // Exclude subtasks dragged on projects
693	      if (draggedTask.parentId) {
694	        return;
695	      }
696	
697	      const projectId = navItemElement.getAttribute('data-project-id');
698	      Log.debug('Task dropped on Project', { taskId: draggedTask.id, projectId });
699	
700	      // We do not want to change the order of the task list if we drop
701	      // to a project or a tag in the main nav
702	      // As there is no way to to cancel a cdk drag action properly,
703	      // we mark the next drop action to be ignored
704	      this._externalDragService.setCancelNextDrop(true);
705	
706	      // also we want the drag action to be finished, before we move the task
707	      // to a different project, otherwise the drag action might throw an error,
708	      // if the dom element is removed before the return animation has finished
709	      const dragref = this._externalDragService.activeDragRef();
710	      dragref?.ended.pipe(take(1)).subscribe(() => {
711	        this._taskService.moveToProject(draggedTask, projectId!);
712	      });
713	    } else if (navItemElement.hasAttribute('data-tag-id')) {
714	      // Task is dropped on a tag
715	      const tagId = navItemElement.getAttribute('data-tag-id');
716	      Log.debug('Task dropped on Tag', { taskId: draggedTask.id, tagId });
717	
718	      this._externalDragService.setCancelNextDrop(true);
719	
720	      // Special case: "Today" tag means to schedule task for today
721	      if (tagId === TODAY_TAG.id) {
722	        this._taskService.addToToday(draggedTask);
723	      } else {
724	        if (!draggedTask.tagIds.includes(tagId!)) {
725	          // tag not yet assigned to task, add it
726	          this._taskService.updateTags(draggedTask, [...draggedTask.tagIds, tagId!]);
727	        } else {
728	          // tag already assigned to task, remove it
729	          this._taskService.updateTags(
730	            draggedTask,
731	            draggedTask.tagIds.filter((t) => t !== tagId),
732	          );
733	        }
734	      }
735	    }
736	
737	    this._externalDragService.setActiveTask(null);
738	  }
739	}
