590	  private _initScrollTracking(): void {
591	    this._subs.add(
592	      this.upperContainerScroll$.subscribe(({ target }) => {
593	        if ((target as HTMLElement).scrollTop !== 0) {
594	          this.layoutService.isWorkViewScrolled.set(true);
595	        } else {
596	          this.layoutService.isWorkViewScrolled.set(false);
597	        }
598	      }),
599	    );
600	  }
601	
602	  /**
603	   * The list of undone tasks actually visible to the user, used by the deselect
604	   * effect to decide whether the selected task has been filtered out of view.
605	   * Returns `null` while a customizer filter is active but its list has not
606	   * emitted yet — the caller then skips deselecting for this run.
607	   *
608	   * `isCustomized()` is synchronous, but `customizeUndoneTasks` defers the
609	   * customized branch by one animation frame (observeOn(animationFrameScheduler)),
610	   * so the two can be momentarily out of step. Until the first emission `toSignal`
611	   * still holds the exact INITIAL_CUSTOMIZED_UNDONE_TASKS reference; compare by
612	   * identity (not by length) so a genuinely empty filtered result `{ list: [] }`
613	   * still counts as "ready" and correctly deselects a now-hidden task.
614	   */
615	  private _getVisibleUndoneTasksForSelection(): TaskWithSubTasks[] | null {
616	    if (!this.customizerService.isCustomized()) {
617	      return this.undoneTasks();
618	    }
619	
620	    const customized = this.customizedUndoneTasks();
621	    const isCustomizedListReady = customized !== INITIAL_CUSTOMIZED_UNDONE_TASKS;
622	    return isCustomizedListReady ? customized.list : null;
623	  }
624	
625	  private _focusItemInWorkViewWhenReady(
626	    taskId: string,
627	    retriesLeft: number = WorkViewComponent._FOCUS_ITEM_MAX_RETRIES,
628	  ): void {
629	    if (this._pendingFocusItemTimeout) {
630	      window.clearTimeout(this._pendingFocusItemTimeout);
631	      this._pendingFocusItemTimeout = undefined;
632	    }
633	
634	    const container = this._splitTopElement;
635	    // Avoid querySelector here — task IDs are nanoid-generated and may start
636	    // with `-` or a digit, which would throw SyntaxError.
637	    const byId = document.getElementById(`t-${taskId}`);
638	    const directMatch = byId && container?.contains(byId) ? byId : null;
639	    const selectedMatch =
640	      this.selectedTaskId() === taskId
641	        ? ((container?.querySelector('task.isSelected') as HTMLElement | null) ?? null)
642	        : null;
643	    const matchedElement = directMatch ?? selectedMatch;
644	    const el =
645	      matchedElement && this._isTaskElementReady(matchedElement) ? matchedElement : null;
646	    recordSearchNavDebug('workView:focusAttempt', {
647	      taskId,
648	      retriesLeft,
649	      selectedTaskId: this.selectedTaskId(),
650	      hasContainer: !!container,
651	      hasDirectMatch: !!directMatch,
652	      hasSelectedMatch: !!selectedMatch,
653	      matchedElementHeight: matchedElement?.getBoundingClientRect().height ?? null,
654	      containerScrollTop: container?.scrollTop ?? null,
655	      containerClientHeight: container?.clientHeight ?? null,
656	      containerScrollHeight: container?.scrollHeight ?? null,
657	    });
658	    if (container && el) {
659	      const relativeTop = this._getRelativeTopWithinContainer(el, container);
660	      const containerCenterOffset = container.clientHeight / 2;
661	      const elementCenterOffset = el.offsetHeight / 2;
662	      const centeredTop = relativeTop - containerCenterOffset + elementCenterOffset;
663	      container.scrollTop = Math.max(centeredTop, 0);
664	      el.focus({ preventScroll: true });
665	      recordSearchNavDebug('workView:focusSuccess', {
666	        taskId,
667	        selectedTaskId: this.selectedTaskId(),
668	        matchedElementId: el.id,
669	        relativeTop,
670	        elementOffsetHeight: el.offsetHeight,
671	        centeredTop,
672	        appliedScrollTop: container.scrollTop,
673	      });
674	      window.setTimeout(() => {
675	        recordSearchNavDebug('workView:focusPostTick', {
676	          taskId,
677	          selectedTaskId: this.selectedTaskId(),
678	          matchedElementId: el.id,
679	          containerScrollTop: container.scrollTop,
680	          containerClientHeight: container.clientHeight,
681	          containerScrollHeight: container.scrollHeight,
682	        });
683	      }, 0);
684	      this._pendingFocusItemTaskId = null;
685	      return;
686	    }
687	
688	    if (retriesLeft <= 0) {
689	      return;
690	    }
691	
692	    this._pendingFocusItemTimeout = window.setTimeout(() => {
693	      this._pendingFocusItemTimeout = undefined;
694	      this._focusItemInWorkViewWhenReady(taskId, retriesLeft - 1);
695	    }, WorkViewComponent._FOCUS_ITEM_RETRY_DELAY);
696	  }
697	
698	  private _getRelativeTopWithinContainer(
699	    el: HTMLElement,
700	    container: HTMLElement,
701	  ): number {
702	    let relativeTop = 0;
703	    let current: HTMLElement | null = el;
704	
705	    while (current && current !== container) {
706	      relativeTop += current.offsetTop;
707	      current = current.offsetParent as HTMLElement | null;
708	    }
709	
710	    return relativeTop;
711	  }
712	
713	  private _isTaskElementReady(el: HTMLElement): boolean {
714	    return (
715	      document.body.contains(el) &&
716	      el.getClientRects().length > 0 &&
717	      el.getBoundingClientRect().height > 0
718	    );
719	  }
720	
721	  private _hasTaskInList(
722	    taskList: TaskWithSubTasks[] | null | undefined,
723	    taskId: string,
724	  ): boolean {
725	    if (!taskList || !taskList.length) {
726	      return false;
727	    }
728	
729	    for (const task of taskList) {
730	      if (!task) {
731	        continue;
732	      }
733	
734	      if (task.id === taskId) {
735	        return true;
736	      }
737	
738	      const subTasks = task.subTasks;
739	      if (Array.isArray(subTasks) && subTasks.length) {
740	        for (const subTask of subTasks) {
741	          if (subTask && subTask.id === taskId) {
742	            return true;
743	          }
744	        }
745	      }
746	    }
747	
748	    return false;
749	  }
750	}
