85	export class ConfigPageComponent implements OnInit {
86	  private readonly _cd = inject(ChangeDetectorRef);
87	  private readonly _route = inject(ActivatedRoute);
88	  private readonly _providerManager = inject(SyncProviderManager);
89	  private readonly _syncWrapperService = inject(SyncWrapperService);
90	  private readonly _pluginBridgeService = inject(PluginBridgeService);
91	  private readonly _snackService = inject(SnackService);
92	  private readonly _shareService = inject(ShareService);
93	  private readonly _userProfileService = inject(UserProfileService);
94	  private readonly _matDialog = inject(MatDialog);
95	  private readonly _localBackupService = inject(LocalBackupService);
96	  private readonly _translateService = inject(TranslateService);
97	  private readonly _isAndroidWebView = inject(IS_ANDROID_WEB_VIEW_TOKEN);
98	
99	  readonly configService = inject(GlobalConfigService);
100	  readonly syncSettingsService = inject(SyncConfigService);
101	  readonly taskWidgetSettingsService = inject(TaskWidgetSettingsService);
102	
103	  T: typeof T = T;
104	
105	  selectedTabIndex = 0;
106	  expandedSection: string | null = null;
107	
108	  // @todo - find better names for tabs configs forms
109	  // Tab-specific form configurations
110	  generalFormCfg: ConfigFormConfig;
111	  globalTasksFormCfg: ConfigFormConfig;
112	  timeTrackingFormCfg: ConfigFormConfig;
113	  pluginsShortcutsFormCfg: ConfigFormConfig;
114	  globalImexFormCfg: ConfigFormConfig;
115	  globalProductivityConfigFormCfg: ConfigFormConfig;
116	  globalCfg?: GlobalConfigState;
117	
118	  // `providerId === null` ⇒ empty state (sync disabled or no provider chosen).
119	  // switchMap drops stale signal writes if a new sync-config emission arrives
120	  // before the previous provider probe resolves — the underlying probe promise
121	  // still runs to completion in the background; only the result is ignored.
122	  // try/catch keeps the stream alive when isReady() rejects (otherwise the
123	  // observable error would kill the subscription and freeze the status).
124	  syncStatus = toSignal(
125	    this.syncSettingsService.syncSettingsForm$.pipe(
126	      switchMap((sync) => {
127	        const providerId = sync.isEnabled
128	          ? (sync.syncProvider as SyncProviderId | null)
129	          : null;
130	        const isEncrypted = !!sync.isEncryptionEnabled;
131	        if (!providerId) {
132	          return of({ providerId: null, needsAuth: false, isEncrypted });
133	        }
134	        return from(
135	          (async () => {
136	            const provider = await this._providerManager.getProviderById(providerId);
137	            const requiresAuth = !!provider?.getAuthHelper;
138	            try {
139	              const isAuthed = !!(await provider?.isReady());
140	              return { providerId, needsAuth: requiresAuth && !isAuthed, isEncrypted };
141	            } catch {
142	              // Don't claim a non-OAuth provider needs auth — only surface
143	              // the auth pill if the provider could plausibly require it.
144	              return { providerId, needsAuth: requiresAuth, isEncrypted };
145	            }
146	          })(),
147	        );
148	      }),
149	    ),
