244	  private _updateKeyboardFormWithPluginShortcuts(shortcuts: PluginShortcutCfg[]): void {
245	    // @todo - make separate core shortcuts and plugins shortcuts settings
246	    // Find keyboard form section in general tab configuration
247	    const keyboardFormIndex = this.generalFormCfg.findIndex(
248	      (section) => section.key === 'keyboard',
249	    );
250	
251	    if (keyboardFormIndex === -1) {
252	      Log.err('Keyboard form section not found');
253	      return;
254	    }
255	
256	    const keyboardSection = this.generalFormCfg[keyboardFormIndex];
257	
258	    // Remove existing plugin shortcuts and header from the form
259	    const filteredItems = (keyboardSection.items || []).filter((item) => {
260	      // Remove plugin shortcut items
261	      if (item.key?.toString().startsWith('plugin_')) {
262	        return false;
263	      }
264	      // Remove plugin shortcuts header
265	      if (
266	        item.type === 'tpl' &&
267	        item.templateOptions?.text ===
268	          (T.GCF.KEYBOARD.PLUGIN_SHORTCUTS || 'Plugin Shortcuts')
269	      ) {
270	        return false;
271	      }
272	      return true;
273	    });
274	
275	    // Add current plugin shortcuts to the form
276	    let newItems = [...filteredItems];
277	    if (shortcuts.length > 0) {
278	      const pluginShortcutItems = createPluginShortcutFormItems(shortcuts);
279	      newItems = [...filteredItems, ...pluginShortcutItems];
280	      Log.log(`Updated keyboard form with ${shortcuts.length} plugin shortcuts`);
281	    } else {
282	      Log.log('No plugin shortcuts to add to keyboard form');
283	    }
284	
285	    // Create a new keyboard section object to trigger change detection
286	    const newKeyboardSection = {
287	      ...keyboardSection,
288	      items: newItems,
289	    };
290	
291	    // Create a new config array to ensure Angular detects the change
292	    this.generalFormCfg = [
293	      ...this.generalFormCfg.slice(0, keyboardFormIndex),
294	      newKeyboardSection,
295	      ...this.generalFormCfg.slice(keyboardFormIndex + 1),
296	    ];
297	
298	    // Trigger change detection
299	    this._cd.detectChanges();
300	  }
