312	  async saveGlobalCfg($event: {
313	    sectionKey: GlobalConfigFormSectionKey | ProjectCfgFormKey;
314	    config: Record<string, unknown>;
315	  }): Promise<void> {
316	    const config = $event.config;
317	    const formSectionKey = $event.sectionKey;
318	
319	    if (!formSectionKey || !config) {
320	      throw new Error('Not enough data');
321	    }
322	
323	    // taskWidget is per-instance (not synced) — handled by a dedicated service
324	    if (formSectionKey === 'taskWidget') {
325	      this.taskWidgetSettingsService.update(config as Partial<TaskWidgetConfig>);
326	      return;
327	    }
328	
329	    // From here on we know it's a real GlobalConfigState section.
330	    const sectionKey = formSectionKey as GlobalConfigSectionKey;
331	
332	    // Check if user is trying to enable an experimental feature
333	    const currentAppFeatures = this.globalCfg?.appFeatures;
334	    if (
335	      sectionKey === 'appFeatures' &&
336	      currentAppFeatures &&
337	      EXPERIMENTAL_APP_FEATURE_KEYS.some(
338	        (key) => config[key] === true && currentAppFeatures[key] === false,
339	      )
340	    ) {
341	      const confirmed = await this._showExperimentalWarningDialog();
342	      if (!confirmed) {
343	        return;
344	      }
345	    }
346	
347	    // Check if user is trying to disable user profiles when multiple profiles exist
348	    if (
349	      sectionKey === 'appFeatures' &&
350	      config.isEnableUserProfiles === false &&
351	      this._userProfileService.hasMultipleProfiles()
352	    ) {
353	      const appFeatures = this.globalCfg?.appFeatures;
354	      // Only show dialog if we're actually changing from true to false
355	      if (appFeatures?.isEnableUserProfiles === true) {
356	        const confirmed = await this._showDisableProfilesDialog();
357	        if (!confirmed) {
358	          // User cancelled, don't save the change
359	          return;
360	        }
361	      }
362	    }
363	
364	    this.configService.updateSection(sectionKey, config);
365	  }
366	
367	  private async _showDisableProfilesDialog(): Promise<boolean> {
368	    const activeProfile = this._userProfileService.activeProfile();
369	    const allProfiles = this._userProfileService.profiles();
370	    const otherProfiles = allProfiles.filter((p) => p.id !== activeProfile?.id);
371	
372	    if (!activeProfile) {
373	      return true; // No active profile, allow disable
374	    }
375	
376	    const dialogRef = this._matDialog.open(DialogDisableProfilesConfirmationComponent, {
377	      data: {
378	        activeProfile,
379	        otherProfiles,
380	      },
381	      width: '600px',
382	      maxWidth: '90vw',
383	      disableClose: true,
384	    });
385	
386	    return new Promise((resolve) => {
387	      dialogRef.afterClosed().subscribe((result) => {
388	        resolve(!!result);
389	      });
390	    });
391	  }
392	
393	  private async _showExperimentalWarningDialog(): Promise<boolean> {
394	    const dialogRef = this._matDialog.open(DialogConfirmComponent, {
395	      restoreFocus: true,
396	      data: {
397	        title: T.GCF.APP_FEATURES.EXPERIMENTAL_WARNING_TITLE,
398	        titleIcon: 'warning',
399	        message: T.GCF.APP_FEATURES.EXPERIMENTAL_WARNING_MSG,
400	        okTxt: T.G.CONFIRM,
401	        cancelTxt: T.G.CANCEL,
402	      },
403	    });
404	    return !!(await firstValueFrom(dialogRef.afterClosed()));
405	  }
406	
407	  getGlobalCfgSection(
408	    sectionKey: GlobalConfigFormSectionKey | ProjectCfgFormKey,
409	  ): GlobalSectionConfig {
410	    if (sectionKey === 'taskWidget') {
411	      return this.taskWidgetSettingsService.settings() as GlobalSectionConfig;
412	    }
413	    return (this.globalCfg as unknown as Record<string, GlobalSectionConfig>)[sectionKey];
414	  }
415	
416	  showLogs(): void {
417	    this._matDialog.open(DialogLogsComponent, {
418	      width: '600px',
419	      maxWidth: '95vw',
420	      data: { logs: Log.exportLogHistory() },
421	    });
422	  }
